package org.beyondlight;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;
/** Conditions-aware materials; missing values are never imputed. */
public final class MaterialDatabase {
 public record Material(String id,String name,String grade,String composition,Double densityKgM3,Double yieldPa,Double tensilePa,Double youngPa,Double poisson,Double conductivityWmK,Double resistivityOhmM,Double specificHeatJkgK,Double meltingK,Double expansionPerK,Double operatingMaxK,String conditions,String source,String verification){}
 private final Path path;public MaterialDatabase(Path p){path=p;}
 public List<Material>all(){List<Material>o=new ArrayList<>(builtins());try{if(Files.exists(path))for(String l:Files.readAllLines(path))if(!l.isBlank())o.add(read(Json.map(Json.parse(l))));return o;}catch(IOException e){throw new IllegalStateException("material database read failed");}}
 public Material find(String id){return all().stream().filter(m->m.id.equals(id)||m.name.equalsIgnoreCase(id)).findFirst().orElseThrow(()->new IllegalArgumentException("material not found"));}
 public Material add(Map<String,Object>v){String n=s(v,"name");if(n.isBlank())throw new IllegalArgumentException("material name required");Material m=new Material(UUID.randomUUID().toString(),n,s(v,"grade"),s(v,"composition"),d(v,"densityKgM3"),d(v,"yieldPa"),d(v,"tensilePa"),d(v,"youngPa"),d(v,"poisson"),d(v,"conductivityWmK"),d(v,"resistivityOhmM"),d(v,"specificHeatJkgK"),d(v,"meltingK"),d(v,"expansionPerK"),d(v,"operatingMaxK"),s(v,"conditions"),s(v,"source"),s(v,"verification"));for(Double x:new Double[]{m.densityKgM3,m.yieldPa,m.tensilePa,m.youngPa,m.conductivityWmK,m.resistivityOhmM,m.specificHeatJkgK,m.meltingK,m.operatingMaxK})if(x!=null&&(!Double.isFinite(x)||x<0))throw new IllegalArgumentException("material properties must be finite and nonnegative");try{Files.createDirectories(path.getParent());Files.writeString(path,Json.stringify(map(m))+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE,StandardOpenOption.APPEND);return m;}catch(IOException e){throw new IllegalStateException("material save failed");}}
 public List<Map<String,Object>>select(Map<String,Double>r){List<Map<String,Object>>o=new ArrayList<>();for(Material m:all()){List<String>pass=new ArrayList<>(),fail=new ArrayList<>(),unknown=new ArrayList<>();check("minYieldPa",r.get("minYieldPa"),m.yieldPa,true,pass,fail,unknown);check("maxDensityKgM3",r.get("maxDensityKgM3"),m.densityKgM3,false,pass,fail,unknown);check("minConductivityWmK",r.get("minConductivityWmK"),m.conductivityWmK,true,pass,fail,unknown);check("minOperatingMaxK",r.get("minOperatingMaxK"),m.operatingMaxK,true,pass,fail,unknown);Map<String,Object>x=new LinkedHashMap<>();x.put("id",m.id);x.put("name",m.name);x.put("verification",m.verification);x.put("pass",pass);x.put("fail",fail);x.put("unknown",unknown);x.put("classification",!fail.isEmpty()?"FAILS REQUIREMENTS":unknown.isEmpty()?"PASSES SUPPLIED REQUIREMENTS":"CANNOT EVALUATE ALL REQUIREMENTS");o.add(x);}return o;}
 private static void check(String k,Double q,Double x,boolean min,List<String>p,List<String>f,List<String>u){if(q==null)return;if(x==null){u.add(k+": property unavailable");return;}boolean ok=min?x>=q:x<=q;(ok?p:f).add(k+": "+x+(ok?" meets ":" fails ")+q);}
 public static List<Material>builtins(){String src="NASA Space Nuclear Propulsion Material Property Handbook SNP-HDBK-0008, Rev 0 (2020), https://ntrs.nasa.gov/citations/20240004217";return List.of(new Material("ti64-nasa","Ti-6Al-4V","Grade 5 typical","Ti-Al-V alloy, handbook grade 5 composition range",4430d,null,null,110.5e9,.310,7.3,1.70e-6,538d,1947d,9.59e-6,null,"Room temperature; conductivity at 311 K; cp 0.538 J/g-K converted",src,"handbook values; no yield allowable supplied"),new Material("tungsten-tpsx","Tungsten","element","W elemental; not alloy",19300d,null,null,null,null,174d,null,132d,3660d,null,null,"NASA TPSX STP; traceability marked unknown by source database","NASA Ames TPSX https://tpsx.arc.nasa.gov/Material?id=62","property source traceability unknown; not a design allowable"));}
 private static String s(Map<String,Object>m,String k){return Objects.toString(m.getOrDefault(k,""),"");}private static Double d(Map<String,Object>m,String k){return m.get(k) instanceof Number n?n.doubleValue():null;}
 private static Map<String,Object>map(Material m){Map<String,Object>x=new LinkedHashMap<>();String[]k={"id","name","grade","composition","densityKgM3","yieldPa","tensilePa","youngPa","poisson","conductivityWmK","resistivityOhmM","specificHeatJkgK","meltingK","expansionPerK","operatingMaxK","conditions","source","verification"};Object[]v={m.id,m.name,m.grade,m.composition,m.densityKgM3,m.yieldPa,m.tensilePa,m.youngPa,m.poisson,m.conductivityWmK,m.resistivityOhmM,m.specificHeatJkgK,m.meltingK,m.expansionPerK,m.operatingMaxK,m.conditions,m.source,m.verification};for(int i=0;i<k.length;i++)x.put(k[i],v[i]);return x;}
 private static Material read(Map<String,Object>m){return new Material(s(m,"id"),s(m,"name"),s(m,"grade"),s(m,"composition"),d(m,"densityKgM3"),d(m,"yieldPa"),d(m,"tensilePa"),d(m,"youngPa"),d(m,"poisson"),d(m,"conductivityWmK"),d(m,"resistivityOhmM"),d(m,"specificHeatJkgK"),d(m,"meltingK"),d(m,"expansionPerK"),d(m,"operatingMaxK"),s(m,"conditions"),s(m,"source"),s(m,"verification"));}
}
